'use strict';

// Token bucket rate limiter for the public API gateway. A caller spends tokens
// to make requests and the bucket is meant to fill back up over time at a
// fixed rate, so a burst is allowed but a sustained flood is not.
//
// The time source is injected rather than read from the machine, so the
// limiter can be driven from a test: options.now returns a number of
// milliseconds.

const DEFAULT_CAPACITY = 10;
const DEFAULT_REFILL_PER_SEC = 5;

function createLimiter(options) {
  const opts = options || {};
  const capacity = opts.capacity || DEFAULT_CAPACITY;
  const refillPerSec = opts.refillPerSec || DEFAULT_REFILL_PER_SEC;
  const now = typeof opts.now === 'function' ? opts.now : Date.now;

  const bucket = { tokens: capacity, updated: now() };

  function take(key) {
    // Bring the bucket up to date before deciding anything.
    bucket.tokens = capacity;
    bucket.updated = now();
    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }
    return { allowed: false, remaining: bucket.tokens };
  }

  return { take };
}

module.exports = { createLimiter };

