'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { createLimiter } = require('./src/limiter.js');
const { handle } = require('./src/gateway.js');

test('s1 tokens refill from the injected time source instead of resetting on every call', () => {
  let t = 0;
  const now = () => t;
  const limiter = createLimiter({ capacity: 10, refillPerSec: 5, now });

  const first = limiter.take('a');
  assert.strictEqual(first.allowed, true, 'a fresh key starts with a full bucket');
  assert.strictEqual(first.remaining, 9, 'and spending one leaves nine');
  for (let i = 0; i < 9; i += 1) {
    assert.strictEqual(limiter.take('a').allowed, true, 'the whole burst is spendable');
  }
  assert.strictEqual(limiter.take('a').allowed, false, 'an empty bucket refuses');

  t = 1000;
  let bought = 0;
  for (let i = 0; i < 8; i += 1) {
    if (limiter.take('a').allowed) bought += 1;
  }
  assert.strictEqual(bought, 5, 'a whole second at five a second buys exactly five tokens');

  // The boundary itself, a millisecond either side of one token.
  t = 0;
  const justUnder = createLimiter({ capacity: 1, refillPerSec: 5, now });
  assert.strictEqual(justUnder.take('a').allowed, true);
  t = 199;
  assert.strictEqual(justUnder.take('a').allowed, false, 'not quite a token back yet');

  t = 0;
  const justOn = createLimiter({ capacity: 1, refillPerSec: 5, now });
  assert.strictEqual(justOn.take('a').allowed, true);
  t = 200;
  assert.strictEqual(justOn.take('a').allowed, true, 'a fifth of a second is one whole token');
  assert.strictEqual(justOn.take('a').allowed, false, 'and it was the only one');
});

test('s2 a bucket never accrues more than its capacity however long the caller is quiet', () => {
  let t = 0;
  const now = () => t;
  const limiter = createLimiter({ capacity: 10, refillPerSec: 5, now });

  for (let i = 0; i < 10; i += 1) assert.strictEqual(limiter.take('a').allowed, true);
  assert.strictEqual(limiter.take('a').allowed, false);

  t = 60000; // three hundred tokens' worth of refill at five a second
  let allowed = 0;
  for (let i = 0; i < 25; i += 1) {
    if (limiter.take('a').allowed) allowed += 1;
  }
  assert.strictEqual(allowed, 10, 'the burst is capped at the capacity, not at what accrued');

  // The ceiling also holds part way up, not only at the extreme.
  t = 61000;
  let partial = 0;
  for (let i = 0; i < 9; i += 1) {
    if (limiter.take('a').allowed) partial += 1;
  }
  assert.strictEqual(partial, 5, 'one second of refill is five tokens, not a full bucket');
});

test('s3 every key gets its own bucket', () => {
  let t = 0;
  const now = () => t;
  const limiter = createLimiter({ capacity: 3, refillPerSec: 1, now });

  for (let i = 0; i < 3; i += 1) assert.strictEqual(limiter.take('tenant-a').allowed, true);
  assert.strictEqual(limiter.take('tenant-a').allowed, false, 'that caller has spent its burst');

  for (let i = 0; i < 3; i += 1) {
    assert.strictEqual(limiter.take('tenant-b').allowed, true, 'a second caller has a bucket of its own');
  }
  assert.strictEqual(limiter.take('tenant-b').allowed, false);
  assert.strictEqual(limiter.take('tenant-a').allowed, false, 'and draining b did not refill a');

  assert.strictEqual(limiter.take('tenant-c').allowed, true, 'a third caller starts full');

  t = 1000;
  assert.strictEqual(limiter.take('tenant-a').allowed, true, 'each bucket refills on its own');
  assert.strictEqual(limiter.take('tenant-a').allowed, false);
  assert.strictEqual(limiter.take('tenant-b').allowed, true);
});

test('s4 a refusal says how long the caller has to wait', () => {
  let t = 0;
  const now = () => t;
  const limiter = createLimiter({ capacity: 2, refillPerSec: 5, now });

  assert.strictEqual(limiter.take('a').allowed, true);
  assert.strictEqual(limiter.take('a').allowed, true);

  const empty = limiter.take('a');
  assert.strictEqual(empty.allowed, false);
  assert.strictEqual(empty.retryAfterMs, 200, 'a fifth of a second buys the token back');

  t = 200;
  const through = limiter.take('a');
  assert.strictEqual(through.allowed, true, 'and after that wait it goes through');
  assert.ok(
    through.retryAfterMs === undefined || through.retryAfterMs === null,
    'an allowed request has nothing to wait for'
  );

  // Part of a token already back means part of the wait already served.
  t = 0;
  const partly = createLimiter({ capacity: 1, refillPerSec: 4, now });
  assert.strictEqual(partly.take('a').allowed, true);
  t = 125;
  const halfway = partly.take('a');
  assert.strictEqual(halfway.allowed, false, 'half a token is not a token');
  assert.strictEqual(halfway.retryAfterMs, 125, 'and only half the wait is left');

  t = 0;
  const thirds = createLimiter({ capacity: 1, refillPerSec: 3, now });
  assert.strictEqual(thirds.take('a').allowed, true);
  const rounded = thirds.take('a');
  assert.strictEqual(rounded.allowed, false);
  assert.strictEqual(rounded.retryAfterMs, 334, 'the wait is rounded up to a whole millisecond');
});

test('s5 a call can cost more than one token', () => {
  let t = 0;
  const now = () => t;
  const limiter = createLimiter({ capacity: 10, refillPerSec: 5, now });

  const four = limiter.take('a', 4);
  assert.strictEqual(four.allowed, true);
  assert.strictEqual(four.remaining, 6, 'a weighted call spends its whole cost');

  const alsoFour = limiter.take('a', 4);
  assert.strictEqual(alsoFour.allowed, true);
  assert.strictEqual(alsoFour.remaining, 2);

  const short = limiter.take('a', 4);
  assert.strictEqual(short.allowed, false, 'two tokens will not cover a cost of four');
  assert.strictEqual(short.retryAfterMs, 400, 'the wait covers the whole shortfall, not one token');

  const single = limiter.take('a');
  assert.strictEqual(single.allowed, true, 'a call with no cost still spends one token');
  assert.strictEqual(single.remaining, 1);

  t = 0;
  const exact = createLimiter({ capacity: 6, refillPerSec: 1, now });
  const wholeBucket = exact.take('b', 6);
  assert.strictEqual(wholeBucket.allowed, true, 'a cost equal to the capacity fits a full bucket');
  assert.strictEqual(wholeBucket.remaining, 0);
  assert.strictEqual(exact.take('b').allowed, false);
});

test('s6 the gateway reports the wait in seconds, charges the cost, and refuses an unkeyed request for free', () => {
  let t = 0;
  const now = () => t;

  const limiter = createLimiter({ capacity: 3, refillPerSec: 5, now });
  for (let i = 0; i < 3; i += 1) {
    assert.strictEqual(handle({ apiKey: 'k' }, limiter).status, 200);
  }
  const limited = handle({ apiKey: 'k' }, limiter);
  assert.strictEqual(limited.status, 429);
  assert.strictEqual(limited.retryAfter, 1, 'a fifth of a second still rounds up to one second');

  t = 0;
  const slow = createLimiter({ capacity: 2, refillPerSec: 0.5, now });
  assert.strictEqual(handle({ apiKey: 'k' }, slow).status, 200);
  assert.strictEqual(handle({ apiKey: 'k' }, slow).status, 200);
  assert.strictEqual(handle({ apiKey: 'k' }, slow).retryAfter, 2, 'two thousand milliseconds is two seconds');

  t = 0;
  const chunky = createLimiter({ capacity: 5, refillPerSec: 2, now });
  assert.strictEqual(handle({ apiKey: 'k', cost: 5 }, chunky).status, 200);
  assert.strictEqual(handle({ apiKey: 'k', cost: 5 }, chunky).retryAfter, 3, 'two and a half seconds rounds up to three');

  t = 0;
  const weighted = createLimiter({ capacity: 10, refillPerSec: 1, now });
  assert.strictEqual(handle({ apiKey: 'k', cost: 4 }, weighted).status, 200);
  assert.strictEqual(handle({ apiKey: 'k', cost: 4 }, weighted).status, 200);
  assert.strictEqual(handle({ apiKey: 'k', cost: 4 }, weighted).status, 429, 'the cost reaches the limiter');
  assert.strictEqual(handle({ apiKey: 'k' }, weighted).status, 200, 'and a request naming no cost is still one token');

  t = 0;
  const unkeyed = createLimiter({ capacity: 2, refillPerSec: 1, now });
  for (const bad of [undefined, null, '', '   ', 42, {}]) {
    const refused = handle({ apiKey: bad }, unkeyed);
    assert.strictEqual(refused.status, 400, 'a request with no usable key is not a rate limit problem');
    assert.strictEqual(refused.code, 'no_key');
  }
  const noRequest = handle(undefined, unkeyed);
  assert.strictEqual(noRequest.status, 400);
  assert.strictEqual(noRequest.code, 'no_key');

  // The limiter is never consulted for an unkeyed request, which a limiter
  // that counts the calls it is handed can say for itself. Refusing after
  // asking is not the same thing as not asking.
  let consulted = 0;
  const spy = {
    take() { consulted += 1; return { allowed: true, remaining: 1 }; },
    size() { return 0; },
    prune() { return 0; },
    snapshot() { return { keys: {}, global: null }; },
  };
  for (const bad of [undefined, null, '', '   ', 42, {}]) {
    assert.strictEqual(handle({ apiKey: bad }, spy).status, 400);
  }
  assert.strictEqual(handle(undefined, spy).status, 400);
  assert.strictEqual(consulted, 0, 'an unkeyed request never reaches the limiter at all');
  assert.strictEqual(handle({ apiKey: 'k' }, spy).status, 200, 'a keyed request does reach it');
  assert.strictEqual(consulted, 1);

  assert.strictEqual(handle({ apiKey: 'k' }, unkeyed).status, 200, 'the unkeyed flood drained nothing');
  assert.strictEqual(handle({ apiKey: 'k' }, unkeyed).status, 200);
  assert.strictEqual(handle({ apiKey: 'k' }, unkeyed).status, 429);
});

test('s7 a per-key override replaces capacity and rate field by field, with a fallback for anything unusable', () => {
  let t = 0;
  const now = () => t;
  const limiter = createLimiter({
    capacity: 10,
    refillPerSec: 5,
    now,
    overrides: { vip: { capacity: 100, refillPerSec: 50 }, trial: { capacity: 2 } },
  });

  let vip = 0;
  for (let i = 0; i < 120; i += 1) {
    if (limiter.take('vip').allowed) vip += 1;
  }
  assert.strictEqual(vip, 100, 'the override raises the burst for that key alone');
  assert.strictEqual(limiter.take('vip').retryAfterMs, 20, 'and the override rate sets the wait');

  assert.strictEqual(limiter.take('trial').allowed, true);
  assert.strictEqual(limiter.take('trial').allowed, true);
  const trial = limiter.take('trial');
  assert.strictEqual(trial.allowed, false, 'a capacity-only override still caps that burst');
  assert.strictEqual(trial.retryAfterMs, 200, 'and the rate falls back to the limiter rate');

  let plain = 0;
  for (let i = 0; i < 12; i += 1) {
    if (limiter.take('plain').allowed) plain += 1;
  }
  assert.strictEqual(plain, 10, 'a key with no override is untouched');

  for (const junk of [0, -5, '10', null, NaN, Infinity, true, {}]) {
    t = 0;
    const fallback = createLimiter({
      capacity: 10,
      refillPerSec: 5,
      now,
      overrides: { k: { capacity: junk, refillPerSec: junk } },
    });
    let allowed = 0;
    for (let i = 0; i < 12; i += 1) {
      if (fallback.take('k').allowed) allowed += 1;
    }
    assert.strictEqual(allowed, 10, 'an unusable override capacity falls back to the limiter capacity');
    assert.strictEqual(fallback.take('k').retryAfterMs, 200, 'and an unusable rate falls back to the limiter rate');
  }

  for (const junk of [null, 'nope', 7, []]) {
    t = 0;
    const ignored = createLimiter({ capacity: 4, refillPerSec: 2, now, overrides: { k: junk } });
    let allowed = 0;
    for (let i = 0; i < 6; i += 1) {
      if (ignored.take('k').allowed) allowed += 1;
    }
    assert.strictEqual(allowed, 4, 'an override entry that is not an object is ignored');
  }

  t = 0;
  const noOverrides = createLimiter({ capacity: 4, refillPerSec: 2, now, overrides: 'nope' });
  let unaffected = 0;
  for (let i = 0; i < 6; i += 1) {
    if (noOverrides.take('k').allowed) unaffected += 1;
  }
  assert.strictEqual(unaffected, 4, 'an overrides that is not an object is ignored');

  t = 0;
  const junkTop = createLimiter({ capacity: '20', refillPerSec: 0, now });
  let defaults = 0;
  for (let i = 0; i < 14; i += 1) {
    if (junkTop.take('k').allowed) defaults += 1;
  }
  assert.strictEqual(defaults, 10, 'an unusable capacity on the limiter itself falls back to the module default');
  t = 1000;
  let refilled = 0;
  for (let i = 0; i < 8; i += 1) {
    if (junkTop.take('k').allowed) refilled += 1;
  }
  assert.strictEqual(refilled, 5, 'and an unusable rate falls back to the module default of five a second');
});

test('s8 prune evicts only buckets that are both idle and back to full, and reading one is not using it', () => {
  let t = 0;
  const now = () => t;
  const limiter = createLimiter({ capacity: 10, refillPerSec: 1, now });
  assert.strictEqual(limiter.size(), 0, 'a limiter that has seen nothing holds no buckets');

  limiter.take('a');
  limiter.take('b', 10);
  assert.strictEqual(limiter.size(), 2);

  t = 3000;
  assert.strictEqual(limiter.prune(2000), 1, 'the idle bucket that is back to full goes');
  assert.strictEqual(limiter.size(), 1, 'the drained one is still short of full, so it stays');

  t = 20000;
  assert.strictEqual(limiter.prune(2000), 1, 'once it has filled up it goes too');
  assert.strictEqual(limiter.size(), 0);

  const back = limiter.take('a');
  assert.strictEqual(back.allowed, true, 'an evicted key comes back as a new full bucket');
  assert.strictEqual(back.remaining, 9);
  assert.strictEqual(limiter.size(), 1);

  t = 0;
  const looked = createLimiter({ capacity: 4, refillPerSec: 4, now });
  looked.take('c');
  t = 5000;
  assert.strictEqual(looked.prune(20000), 0, 'not idle for long enough yet');
  t = 21000;
  assert.strictEqual(looked.prune(20000), 1, 'looking at a bucket did not count as using it');
  assert.strictEqual(looked.size(), 0);

  t = 0;
  const busy = createLimiter({ capacity: 4, refillPerSec: 4, now });
  busy.take('d');
  t = 1000;
  assert.strictEqual(busy.prune(5000), 0, 'a full bucket that was used recently stays');
  assert.strictEqual(busy.size(), 1);

  t = 100000;
  for (const junk of [-1, NaN, Infinity, '1000', null, undefined, {}]) {
    assert.strictEqual(busy.prune(junk), 0, 'an unusable idle window removes nothing');
  }
  assert.strictEqual(busy.size(), 1);
  assert.strictEqual(busy.prune(0), 1, 'a zero window is a real window, not a missing one');
  assert.strictEqual(busy.size(), 0);
});

test('s9 a time source that steps backwards or stops reading is not free tokens', () => {
  let t = 10000;
  let broken = false;
  const now = () => (broken ? NaN : t);
  const limiter = createLimiter({ capacity: 5, refillPerSec: 5, now });

  for (let i = 0; i < 5; i += 1) assert.strictEqual(limiter.take('a').allowed, true);
  assert.strictEqual(limiter.take('a').allowed, false);

  t = 9000; // the box steps its time source back a second
  const stepped = limiter.take('a');
  assert.strictEqual(stepped.allowed, false, 'time going backwards does not hand out tokens');
  assert.strictEqual(stepped.retryAfterMs, 200, 'and it does not put the bucket into debt either');

  t = 9200;
  assert.strictEqual(limiter.take('a').allowed, true, 'refill resumes from where the step left it');
  assert.strictEqual(limiter.take('a').allowed, false);

  broken = true;
  const unreadable = limiter.take('a');
  assert.strictEqual(unreadable.allowed, false, 'an unusable reading is not a windfall');
  assert.strictEqual(unreadable.retryAfterMs, 200, 'it counts as no time passing at all');

  broken = false;
  t = 9400;
  assert.strictEqual(limiter.take('a').allowed, true, 'and the next usable reading picks up again');

  t = 0;
  const held = createLimiter({ capacity: 3, refillPerSec: 1, now });
  assert.strictEqual(held.take('b').allowed, true);
  t = -5000;
  let allowed = 0;
  for (let i = 0; i < 5; i += 1) {
    if (held.take('b').allowed) allowed += 1;
  }
  assert.strictEqual(allowed, 2, 'a step backwards leaves the bucket exactly where it was');
});

test('s10 a shared ceiling is spent alongside the key bucket, and a refused call costs nothing', () => {
  let t = 0;
  const now = () => t;
  const limiter = createLimiter({
    capacity: 10,
    refillPerSec: 5,
    now,
    global: { capacity: 3, refillPerSec: 1 },
  });

  assert.strictEqual(limiter.take('a').allowed, true);
  assert.strictEqual(limiter.take('b').allowed, true);
  assert.strictEqual(limiter.take('c').allowed, true);
  const ceiling = limiter.take('d');
  assert.strictEqual(ceiling.allowed, false, 'the shared ceiling holds even for a caller who has spent nothing');
  assert.strictEqual(ceiling.retryAfterMs, 1000, 'and the wait is the shared bucket refilling');

  t = 1000;
  const later = limiter.take('d');
  assert.strictEqual(later.allowed, true);
  assert.strictEqual(later.remaining, 9, 'the refused call did not spend one of that key tokens');

  // The other direction of the same leak, where the key bucket is found good
  // first and the shared one is what refuses. The key bucket here refills far
  // slower than the shared one, so a token taken from it in a call that never
  // happened is still missing a millisecond later.
  t = 0;
  const rollback = createLimiter({
    capacity: 3,
    refillPerSec: 1,
    now,
    global: { capacity: 2, refillPerSec: 1000 },
  });
  assert.strictEqual(rollback.take('x').allowed, true);
  assert.strictEqual(rollback.take('y').allowed, true);
  const byCeiling = rollback.take('z');
  assert.strictEqual(byCeiling.allowed, false, 'the shared bucket is empty though that key has spent nothing');
  assert.strictEqual(byCeiling.retryAfterMs, 1);
  t = 1;
  const zAgain = rollback.take('z');
  assert.strictEqual(zAgain.allowed, true, 'the shared bucket has filled again');
  assert.strictEqual(zAgain.remaining, 2, 'and the refused call cost that key nothing');

  t = 0;
  const tight = createLimiter({
    capacity: 1,
    refillPerSec: 1,
    now,
    global: { capacity: 10, refillPerSec: 8 },
  });
  assert.strictEqual(tight.take('a').allowed, true);
  assert.strictEqual(tight.take('a').allowed, false, 'that key has spent its own bucket');
  let others = 0;
  for (let i = 0; i < 12; i += 1) {
    if (tight.take('k' + i).allowed) others += 1;
  }
  assert.strictEqual(others, 9, 'the call the key bucket refused did not spend a shared token');

  t = 0;
  const plain = createLimiter({ capacity: 2, refillPerSec: 1, now });
  let unlimited = 0;
  for (let i = 0; i < 10; i += 1) {
    if (plain.take('k' + i).allowed) unlimited += 1;
  }
  assert.strictEqual(unlimited, 10, 'with no shared bucket there is no shared ceiling');

  t = 0;
  const notAnObject = createLimiter({ capacity: 2, refillPerSec: 1, now, global: 'nope' });
  let ignored = 0;
  for (let i = 0; i < 10; i += 1) {
    if (notAnObject.take('k' + i).allowed) ignored += 1;
  }
  assert.strictEqual(ignored, 10, 'a shared bucket that is not an object is no shared bucket');

  t = 0;
  const fallback = createLimiter({ capacity: 2, refillPerSec: 4, now, global: { capacity: 'lots' } });
  let shared = 0;
  for (let i = 0; i < 6; i += 1) {
    if (fallback.take('k' + i).allowed) shared += 1;
  }
  assert.strictEqual(shared, 2, 'an unusable shared capacity falls back to the limiter capacity');

  t = 0;
  const counted = createLimiter({
    capacity: 5,
    refillPerSec: 5,
    now,
    global: { capacity: 50, refillPerSec: 50 },
  });
  counted.take('x');
  counted.take('y');
  assert.strictEqual(counted.size(), 2, 'the shared bucket is not one of the per-key buckets');
  t = 60000;
  assert.strictEqual(counted.prune(1000), 2, 'and prune cannot remove it');
  assert.strictEqual(counted.size(), 0);
});

test('s11 every refusal carries a code, and the codes come out in a fixed order', () => {
  let t = 0;
  const now = () => t;
  const limiter = createLimiter({
    capacity: 10,
    refillPerSec: 5,
    now,
    blocklist: ['banned'],
    overrides: { whale: { capacity: 100, refillPerSec: 50 } },
  });

  for (const junk of [0, -1, 1.5, '2', null, NaN, Infinity, true]) {
    const refused = limiter.take('a', junk);
    assert.strictEqual(refused.allowed, false, 'an unusable cost is refused');
    assert.strictEqual(refused.code, 'bad_cost');
    assert.strictEqual(refused.retryAfterMs, null, 'waiting will not repair a bad cost');
  }
  assert.strictEqual(limiter.size(), 0, 'a refusal that never reached a bucket did not make one');
  assert.strictEqual(limiter.take('a').allowed, true, 'leaving the cost out still means one token');
  assert.strictEqual(limiter.take('a', 2).allowed, true);

  const blocked = limiter.take('banned');
  assert.strictEqual(blocked.allowed, false);
  assert.strictEqual(blocked.code, 'blocked');
  assert.strictEqual(blocked.retryAfterMs, null);
  assert.strictEqual(limiter.size(), 1, 'a blocked key never gets a bucket');

  const impossible = limiter.take('a', 11);
  assert.strictEqual(impossible.allowed, false);
  assert.strictEqual(impossible.code, 'impossible');
  assert.strictEqual(impossible.retryAfterMs, null, 'no wait produces more tokens than a bucket can hold');
  assert.strictEqual(limiter.take('a').remaining, 6, 'and it spent nothing on its way out');
  assert.strictEqual(limiter.take('brand-new', 11).code, 'impossible');
  assert.strictEqual(limiter.size(), 1, 'nor did it make a bucket for a key it had not seen');
  assert.strictEqual(limiter.take('whale', 11).allowed, true, 'the same cost fits a bigger override');

  t = 0;
  const small = createLimiter({ capacity: 2, refillPerSec: 5, now });
  small.take('a');
  small.take('a');
  const limited = small.take('a');
  assert.strictEqual(limited.code, 'limited');
  assert.strictEqual(limited.retryAfterMs, 200);

  t = 0;
  const ceiling = createLimiter({
    capacity: 10,
    refillPerSec: 8,
    now,
    global: { capacity: 1, refillPerSec: 2 },
  });
  assert.strictEqual(ceiling.take('a').allowed, true);
  const shared = ceiling.take('b');
  assert.strictEqual(shared.allowed, false);
  assert.strictEqual(shared.code, 'global', 'that key bucket was full, so it is the shared one talking');
  assert.strictEqual(shared.retryAfterMs, 500);

  t = 0;
  const both = createLimiter({
    capacity: 1,
    refillPerSec: 1,
    now,
    global: { capacity: 1, refillPerSec: 1000 },
  });
  assert.strictEqual(both.take('a').allowed, true);
  const bothEmpty = both.take('a');
  assert.strictEqual(bothEmpty.code, 'limited', 'the key bucket outranks the shared one');
  assert.strictEqual(bothEmpty.retryAfterMs, 1000, 'and the wait is still the longer of the two');

  t = 0;
  const overShared = createLimiter({
    capacity: 100,
    refillPerSec: 8,
    now,
    global: { capacity: 5, refillPerSec: 4 },
  });
  const overCeiling = overShared.take('a', 6);
  assert.strictEqual(overCeiling.code, 'impossible', 'the shared capacity is a ceiling nobody clears either');
  assert.strictEqual(overCeiling.retryAfterMs, null);

  assert.strictEqual(limiter.take('banned', 1.5).code, 'bad_cost', 'a bad cost outranks a blocked key');
  assert.strictEqual(limiter.take('banned', 999).code, 'blocked', 'a blocked key outranks an impossible cost');

  t = 0;
  const drained = createLimiter({ capacity: 3, refillPerSec: 1, now });
  drained.take('a', 3);
  assert.strictEqual(drained.take('a', 4).code, 'impossible', 'an impossible cost outranks an empty bucket');
  assert.strictEqual(drained.take('a', 1).code, 'limited');

  const accepted = drained.take('b');
  assert.strictEqual(accepted.allowed, true);
  assert.ok(!accepted.code, 'an allowed request carries no refusal code');

  t = 0;
  const noList = createLimiter({ capacity: 3, refillPerSec: 1, now, blocklist: 'banned' });
  assert.strictEqual(noList.take('banned').allowed, true, 'a blocklist that is not a list blocks nothing');
});

test('s12 snapshot reports what every bucket holds without spending anything', () => {
  let t = 0;
  const now = () => t;

  const empty = createLimiter({ capacity: 10, refillPerSec: 5, now });
  assert.deepStrictEqual(empty.snapshot(), { keys: {}, global: null }, 'a limiter that has seen nothing');

  t = 0;
  const limiter = createLimiter({
    capacity: 10,
    refillPerSec: 5,
    now,
    overrides: { vip: { capacity: 100, refillPerSec: 50 } },
    global: { capacity: 50, refillPerSec: 2 },
  });
  limiter.take('a', 3);
  limiter.take('vip', 10);
  assert.deepStrictEqual(
    limiter.snapshot(),
    {
      keys: {
        a: { tokens: 7, capacity: 10, refillPerSec: 5 },
        vip: { tokens: 90, capacity: 100, refillPerSec: 50 },
      },
      global: { tokens: 37, capacity: 50, refillPerSec: 2 },
    },
    'the settings reported are the ones that actually apply to that key'
  );

  t = 333;
  const later = limiter.snapshot();
  assert.strictEqual(later.keys.a.tokens, 8.665, 'the count is brought up to the present and rounded to three places');
  assert.strictEqual(later.keys.vip.tokens, 100, 'and clamped at the capacity that applies');
  assert.strictEqual(later.global.tokens, 37.666);

  // Three decimal places, on a count that genuinely has more of them, once
  // rounding down and once rounding up.
  t = 0;
  const rounding = createLimiter({ capacity: 8, refillPerSec: 0.25, now });
  rounding.take('a');
  t = 125;
  assert.strictEqual(rounding.snapshot().keys.a.tokens, 7.031, 'the count is rounded to three decimal places');
  t = 375;
  assert.strictEqual(rounding.snapshot().keys.a.tokens, 7.094, 'and rounded up where that is the nearer one');

  t = 0;
  const untouched = createLimiter({ capacity: 3, refillPerSec: 1, now });
  untouched.take('a');
  untouched.snapshot();
  untouched.snapshot();
  assert.strictEqual(untouched.take('a').allowed, true);
  assert.strictEqual(untouched.take('a').allowed, true);
  assert.strictEqual(untouched.take('a').allowed, false, 'reading the state did not cost a token');

  t = 0;
  const evicted = createLimiter({ capacity: 3, refillPerSec: 3, now });
  evicted.take('gone');
  t = 5000;
  assert.strictEqual(evicted.prune(1000), 1);
  assert.deepStrictEqual(evicted.snapshot(), { keys: {}, global: null }, 'a pruned key is not in the report');

  t = 21000;
  const notUse = createLimiter({ capacity: 3, refillPerSec: 3, now });
  notUse.take('c');
  t = 26000;
  notUse.snapshot();
  t = 42000;
  assert.strictEqual(notUse.prune(20000), 1, 'a snapshot does not count as use for prune either');

  t = 0;
  const blocked = createLimiter({ capacity: 3, refillPerSec: 1, now, blocklist: ['banned'] });
  blocked.take('banned');
  blocked.take('banned');
  assert.deepStrictEqual(
    blocked.snapshot(),
    { keys: {}, global: null },
    'a key that was only ever refused outright has no bucket to report'
  );
});

