'use strict';

// Token bucket rate limiter for the public API gateway. A caller spends tokens
// to make requests and the bucket fills back up over time at a fixed rate, so
// a burst is allowed but a sustained flood is not.
//
// The time source is injected rather than read from the machine, so the
// limiter can be driven from a test: options.now returns a number of
// milliseconds.

const DEFAULT_CAPACITY = 10;
const DEFAULT_REFILL_PER_SEC = 5;

function positive(value, fallback) {
  return typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : fallback;
}

function isPlainObject(value) {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

function createLimiter(options) {
  const opts = isPlainObject(options) ? options : {};
  const now = typeof opts.now === 'function' ? opts.now : Date.now;

  const capacity = positive(opts.capacity, DEFAULT_CAPACITY);
  const refillPerSec = positive(opts.refillPerSec, DEFAULT_REFILL_PER_SEC);
  const overrides = isPlainObject(opts.overrides) ? opts.overrides : {};
  const blocklist = new Set(Array.isArray(opts.blocklist) ? opts.blocklist.map(String) : []);

  // A reading that is not a finite number is ignored and the last usable one
  // stands, so a broken time source cannot conjure tokens out of nothing.
  let reading = 0;
  const firstReading = now();
  if (typeof firstReading === 'number' && Number.isFinite(firstReading)) reading = firstReading;

  function read() {
    const raw = now();
    if (typeof raw === 'number' && Number.isFinite(raw)) reading = raw;
    return reading;
  }

  function settingsFor(key) {
    const entry = Object.prototype.hasOwnProperty.call(overrides, key) ? overrides[key] : null;
    const o = isPlainObject(entry) ? entry : {};
    return {
      capacity: positive(o.capacity, capacity),
      refillPerSec: positive(o.refillPerSec, refillPerSec),
    };
  }

  const sharedSettings = isPlainObject(opts.global)
    ? {
        capacity: positive(opts.global.capacity, capacity),
        refillPerSec: positive(opts.global.refillPerSec, refillPerSec),
      }
    : null;

  const buckets = new Map();
  const shared = sharedSettings
    ? { tokens: sharedSettings.capacity, updated: reading, used: reading }
    : null;

  // What the bucket would hold at `at`, without writing anything down: reading
  // a bucket is not using it, so prune and snapshot go through here.
  function tokensAt(bucket, settings, at) {
    if (at <= bucket.updated) return bucket.tokens;
    const gained = ((at - bucket.updated) / 1000) * settings.refillPerSec;
    return Math.min(settings.capacity, bucket.tokens + gained);
  }

  function refill(bucket, settings, at) {
    if (at < bucket.updated) {
      // The time source stepped backwards. Measure from the new reading rather
      // than letting a negative gap push the bucket into debt.
      bucket.updated = at;
      return;
    }
    bucket.tokens = tokensAt(bucket, settings, at);
    bucket.updated = at;
  }

  function bucketFor(key, settings, at) {
    let bucket = buckets.get(key);
    if (!bucket) {
      bucket = { tokens: settings.capacity, updated: at, used: at };
      buckets.set(key, bucket);
    } else {
      refill(bucket, settings, at);
    }
    return bucket;
  }

  function waitFor(bucket, settings, cost) {
    const short = cost - bucket.tokens;
    if (short <= 0) return 0;
    return Math.ceil((short / settings.refillPerSec) * 1000);
  }

  // Refusal codes come out in a fixed order, because the gateway shows one:
  // bad_cost, blocked, impossible, limited, global.
  function take(key, cost) {
    const want = cost === undefined ? 1 : cost;
    if (typeof want !== 'number' || !Number.isInteger(want) || want < 1) {
      return { allowed: false, code: 'bad_cost', retryAfterMs: null };
    }
    const id = String(key);
    if (blocklist.has(id)) {
      return { allowed: false, code: 'blocked', retryAfterMs: null };
    }
    const settings = settingsFor(id);
    if (want > settings.capacity || (sharedSettings && want > sharedSettings.capacity)) {
      return { allowed: false, code: 'impossible', retryAfterMs: null };
    }

    const at = read();
    const bucket = bucketFor(id, settings, at);
    bucket.used = at;
    const keyWait = waitFor(bucket, settings, want);
    let sharedWait = 0;
    if (shared) {
      refill(shared, sharedSettings, at);
      shared.used = at;
      sharedWait = waitFor(shared, sharedSettings, want);
    }
    if (keyWait > 0 || sharedWait > 0) {
      // A call that did not happen costs nothing on either bucket.
      return {
        allowed: false,
        code: keyWait > 0 ? 'limited' : 'global',
        retryAfterMs: Math.max(keyWait, sharedWait),
      };
    }
    bucket.tokens -= want;
    if (shared) shared.tokens -= want;
    return { allowed: true, remaining: bucket.tokens };
  }

  function size() {
    return buckets.size;
  }

  function prune(idleMs) {
    if (typeof idleMs !== 'number' || !Number.isFinite(idleMs) || idleMs < 0) return 0;
    const at = read();
    let removed = 0;
    for (const [key, bucket] of [...buckets.entries()]) {
      const settings = settingsFor(key);
      const idleFor = at - bucket.used;
      if (idleFor >= idleMs && tokensAt(bucket, settings, at) >= settings.capacity) {
        buckets.delete(key);
        removed += 1;
      }
    }
    return removed;
  }

  function round3(value) {
    return Math.round(value * 1000) / 1000;
  }

  function stateOf(bucket, settings, at) {
    return {
      tokens: round3(tokensAt(bucket, settings, at)),
      capacity: settings.capacity,
      refillPerSec: settings.refillPerSec,
    };
  }

  function snapshot() {
    const at = read();
    const keys = {};
    for (const [key, bucket] of buckets.entries()) {
      keys[key] = stateOf(bucket, settingsFor(key), at);
    }
    return {
      keys,
      global: shared ? stateOf(shared, sharedSettings, at) : null,
    };
  }

  return { take, size, prune, snapshot };
}

module.exports = { createLimiter };

