'use strict';

// The public API gateway. Every request is charged to the caller's API key
// before it is allowed anywhere near a route handler.

function usableKey(value) {
  return typeof value === 'string' && value.trim().length > 0;
}

function handle(request, limiter) {
  const req = request && typeof request === 'object' ? request : {};
  if (!usableKey(req.apiKey)) {
    return { status: 400, code: 'no_key', body: { error: 'an API key is required' } };
  }
  const result = limiter.take(req.apiKey, req.cost);
  if (!result.allowed) {
    const response = { status: 429, body: { error: 'too many requests' } };
    const ms = result.retryAfterMs;
    if (typeof ms === 'number' && Number.isFinite(ms)) {
      // The header is counted in seconds and the limiter counts milliseconds.
      response.retryAfter = Math.max(1, Math.ceil(ms / 1000));
    }
    return response;
  }
  return { status: 200, body: { ok: true } };
}

module.exports = { handle };
